insert into public.exercises (id, slug, name_de, name_en, description, instructions, common_mistakes, cues, mechanic, movement_pattern, laterality, tracking_type, difficulty, resistance_profile, systemic_fatigue, load_increment_kg, video_url) values
  ('72bc637a-e334-517b-89a0-03153fca2585', 'barbell-bench-press', 'Bankdrücken (Langhantel)', 'Barbell bench press', 'Die klassische Grundübung für Brust, vordere Schulter und Trizeps. Erlaubt hohe Lasten und gut messbaren Fortschritt.', array['Auf die Bank legen, Augen unter der Stange, Füße fest am Boden.', 'Schulterblätter zusammen- und nach unten ziehen, leichtes Hohlkreuz.', 'Stange etwas weiter als schulterbreit greifen und aus der Ablage heben.', 'Kontrolliert zur unteren Brust absenken, Ellbogen etwa 45–70° vom Körper.', 'Stange nach oben und leicht Richtung Ablage drücken, bis die Arme gestreckt sind.'], array['Stange auf der Brust abfedern lassen', 'Ellbogen 90° seitlich abspreizen – belastet die Schulter', 'Gesäß hebt von der Bank ab'], array['Schulterblätter in die Hosentaschen', 'Stange auseinanderbiegen'], 'compound', 'horizontal_push', 'bilateral', 'weight_reps', 'intermediate', 'mid_range', 3, 2.5, 'https://www.youtube.com/watch?v=rT7DgCr-3pg'),
  ('0906fb35-216e-51d2-b20f-e891e609063a', 'dumbbell-bench-press', 'Bankdrücken (Kurzhantel)', 'Dumbbell bench press', 'Wie Bankdrücken, aber mit größerem Bewegungsumfang und freier Handstellung. Schonender für die Schultern und gut ohne Rack.', array['Mit den Kurzhanteln auf den Oberschenkeln hinsetzen und kontrolliert zurücklegen.', 'Schulterblätter zurückziehen, Hanteln über der Brust, Handflächen Richtung Füße.', 'Hanteln seitlich der Brust absenken, bis eine deutliche Dehnung spürbar ist.', 'Nach oben drücken, ohne die Hanteln oben aneinanderzuschlagen.'], array['Zu wenig Tiefe', 'Hanteln fallen am Ende unkontrolliert zur Seite'], array['Tief in die Dehnung', 'Ellbogen unter den Handgelenken'], 'compound', 'horizontal_push', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 2, 2, 'https://www.youtube.com/watch?v=VmB1G1K7v94'),
  ('83b33367-4535-5574-a2b1-8f3efc3a39bb', 'incline-dumbbell-press', 'Schrägbankdrücken (Kurzhantel)', 'Incline dumbbell press', 'Drücken auf der Schrägbank (ca. 30°) betont die obere Brust – optisch wichtig für eine volle Brustpartie.', array['Bank auf etwa 30° einstellen – steiler verlagert die Arbeit auf die Schulter.', 'Schulterblätter zurückziehen, Hanteln über der oberen Brust.', 'Langsam absenken, bis die Oberarme etwa auf Höhe der Brust sind.', 'Nach oben und leicht zusammen drücken.'], array['Bank zu steil', 'Schultern rollen nach vorne'], array['Brust zur Decke', 'Kontrolliert runter, kraftvoll hoch'], 'compound', 'horizontal_push', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 2, 2, 'https://www.youtube.com/watch?v=8iPEnn-ltC8'),
  ('7dd1d491-32fc-53f0-9f31-b809a1e3bbe5', 'machine-chest-press', 'Brustpresse (Maschine)', 'Machine chest press', 'Geführtes Drücken mit stabiler Bahn. Ideal, um nah ans Muskelversagen zu gehen, ohne Gleichgewicht halten zu müssen.', array['Sitz so einstellen, dass die Griffe auf Höhe der mittleren Brust sind.', 'Schulterblätter an die Lehne ziehen.', 'Griffe nach vorne drücken, ohne die Ellbogen ganz durchzustrecken.', 'Langsam zurückführen, bis die Brust gedehnt ist.'], array['Sitz zu hoch oder zu tief', 'Schultern lösen sich von der Lehne'], array['Rücken an die Lehne', 'Langsam zurück in die Dehnung'], 'compound', 'horizontal_push', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 2, 2.5, 'https://www.youtube.com/watch?v=xUm0BiZCWlQ'),
  ('58a95467-3339-597c-9b73-a5140611c2cd', 'push-up', 'Liegestütz', 'Push-up', 'Drücken mit Körpergewicht – überall machbar. Steigern über Wiederholungen, erhöhte Füße oder Zusatzgewicht.', array['Hände etwas weiter als schulterbreit aufsetzen, Körper bildet eine Linie.', 'Bauch und Gesäß anspannen.', 'Brust kontrolliert bis knapp über den Boden senken, Ellbogen schräg nach hinten.', 'Kraftvoll hochdrücken.'], array['Hüfte hängt durch', 'Nur halbe Bewegung'], array['Körper wie ein Brett', 'Brust zum Boden, nicht das Kinn'], 'compound', 'horizontal_push', 'bilateral', 'bodyweight_reps', 'beginner', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=IODxDxX7oi4'),
  ('32a449e9-9562-56ba-815d-4b49be1bdde8', 'dips', 'Dips (Barren)', 'Parallel bar dips', 'Sehr effektiv für untere Brust und Trizeps mit starker Dehnung in der unteren Position.', array['Auf den Barren stützen, Arme gestreckt, Oberkörper leicht nach vorne geneigt.', 'Kontrolliert absenken, bis die Oberarme etwa parallel zum Boden sind.', 'Kurz in der Dehnung halten, ohne abzufedern.', 'Nach oben drücken, bis die Arme wieder gestreckt sind.'], array['Zu tief bei Schulterbeschwerden', 'Schultern ziehen zu den Ohren'], array['Brust raus, Schultern tief', 'Langsam in die Dehnung'], 'compound', 'horizontal_push', 'bilateral', 'bodyweight_reps', 'intermediate', 'lengthened', 2, 2.5, 'https://www.youtube.com/watch?v=85u_8mz5lBA'),
  ('87ea307f-b456-5b2a-ac5c-63488a3c011e', 'cable-fly', 'Kabel-Flys', 'Cable fly', 'Isolationsübung mit gleichmäßiger Spannung über den ganzen Bewegungsweg. Gut für Pump und Mind-Muscle-Connection.', array['Kabel auf Schulterhöhe einstellen, mittig zwischen die Türme stellen, Schrittstellung.', 'Arme leicht gebeugt, Brust heraus.', 'Griffe in einem Bogen vor der Brust zusammenführen.', 'Langsam zurück, bis die Brust deutlich gedehnt ist.'], array['Arme zu stark beugen – wird zum Drücken', 'Oberkörper schwingt mit'], array['Einen großen Baum umarmen', 'Ellbogen bleiben gleich gebeugt'], 'isolation', 'shoulder_horizontal_adduction', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=8Um35Es-ROE'),
  ('2c65acf3-a6ec-5dbf-bfcf-d2e3caf76fe6', 'pec-deck', 'Butterfly (Maschine)', 'Pec deck', 'Geführte Brust-Isolation – einfach zu erlernen und sicher bis nahe ans Versagen.', array['Sitz so einstellen, dass die Griffe auf Brusthöhe sind.', 'Rücken an die Lehne, Schultern tief.', 'Griffe vor der Brust zusammenführen und kurz anspannen.', 'Langsam öffnen, bis die Brust gedehnt ist.'], array['Schultern rollen nach vorne', 'Gewicht fällt unkontrolliert zurück'], array['Brust zusammenpressen', 'Zurück in die Dehnung bremsen'], 'isolation', 'shoulder_horizontal_adduction', 'bilateral', 'weight_reps', 'beginner', 'shortened', 1, 2.5, 'https://www.youtube.com/watch?v=K2VJ4HeXb4s'),
  ('be46633e-fc70-5d72-b749-daf590ef90d0', 'dumbbell-fly', 'Flys (Kurzhantel)', 'Dumbbell fly', 'Belastet die Brust vor allem in gedehnter Position. Mit moderatem Gewicht und sauberer Technik ausführen.', array['Auf der Flachbank liegend, Hanteln über der Brust, Arme leicht gebeugt.', 'In einem weiten Bogen seitlich absenken, bis die Brust gedehnt ist.', 'Ellbogenwinkel dabei nicht verändern.', 'Im gleichen Bogen zurück nach oben führen.'], array['Zu schwer – Schulter wird überlastet', 'Arme werden gebeugt und gedrückt'], array['Weiter Bogen', 'Dehnung kontrollieren, nicht fallen lassen'], 'isolation', 'shoulder_horizontal_adduction', 'bilateral', 'weight_reps', 'intermediate', 'lengthened', 1, 2, 'https://www.youtube.com/watch?v=eozdVDA78K0'),
  ('dbb835b3-0eea-52fb-b0d8-27ee0bddb449', 'overhead-press', 'Schulterdrücken stehend (Langhantel)', 'Standing overhead press', 'Grundübung für die Schultern mit viel Rumpfstabilität. Trainiert vor allem die vordere Schulter.', array['Stange schulterbreit greifen und auf der vorderen Schulter aus dem Rack nehmen.', 'Gesäß und Bauch fest anspannen, Füße hüftbreit.', 'Stange senkrecht über den Kopf drücken, Kopf dabei leicht zurücknehmen.', 'Oben Kopf unter die Stange schieben, dann kontrolliert absenken.'], array['Starkes Hohlkreuz', 'Stange bewegt sich im Bogen um den Kopf'], array['Gesäß anspannen', 'Stange senkrecht, Kopf ausweichen lassen'], 'compound', 'vertical_push', 'bilateral', 'weight_reps', 'intermediate', 'mid_range', 3, 2.5, 'https://www.youtube.com/watch?v=_RlRDWO2jfg'),
  ('6dfd6fba-1f4d-554b-bd9f-08306e161c4b', 'seated-dumbbell-shoulder-press', 'Schulterdrücken sitzend (Kurzhantel)', 'Seated dumbbell shoulder press', 'Stabileres Schulterdrücken mit Rückenlehne – leichter zu lernen als die stehende Variante.', array['Bank fast senkrecht einstellen, Hanteln auf Schulterhöhe.', 'Ellbogen leicht vor dem Körper, Handflächen nach vorne.', 'Hanteln über den Kopf drücken, ohne sie oben zusammenzuschlagen.', 'Kontrolliert bis auf Ohr- bis Kinnhöhe absenken.'], array['Hohlkreuz, Gesäß rutscht nach vorne', 'Nur halbe Bewegung'], array['Rücken an die Lehne', 'Ellbogen unter den Händen'], 'compound', 'vertical_push', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 2, 2, 'https://www.youtube.com/watch?v=qEwKCR5JCog'),
  ('cd4cb9c3-8ee5-5912-81d4-e593db7cb1a2', 'dumbbell-lateral-raise', 'Seitheben (Kurzhantel)', 'Dumbbell lateral raise', 'Die wichtigste Übung für breite Schultern: trainiert die seitliche Schulter, die bei Druckübungen kaum mitarbeitet.', array['Aufrecht stehen, Hanteln seitlich, Arme leicht gebeugt.', 'Arme seitlich anheben, bis sie etwa waagerecht sind.', 'Ellbogen führen die Bewegung, kleine Finger nicht höher als der Daumen.', 'Langsam absenken, ohne die Spannung ganz zu verlieren.'], array['Schwung aus dem Oberkörper', 'Schultern ziehen zu den Ohren', 'Zu schwer'], array['Nach außen, nicht nach oben', 'Ellbogen führen'], 'isolation', 'shoulder_abduction', 'bilateral', 'weight_reps', 'beginner', 'shortened', 1, 1, 'https://www.youtube.com/watch?v=3VcKaXpzqRo'),
  ('b1edd78e-fcd6-5e04-8401-97dfd1c0d7d8', 'cable-lateral-raise', 'Seitheben am Kabel', 'Cable lateral raise', 'Seitheben mit Kabel von unten: Die Spannung beginnt schon in der gedehnten unteren Position.', array['Kabel ganz unten einstellen, seitlich zum Turm stellen, Griff mit der äußeren Hand.', 'Kabel verläuft vor oder hinter dem Körper, Arm leicht gebeugt.', 'Arm seitlich bis etwa Schulterhöhe heben.', 'Langsam zurück, bis die Schulter gedehnt ist.'], array['Oberkörper kippt weg', 'Bewegung zu kurz'], array['Weit nach außen führen', 'Unten nicht ablegen'], 'isolation', 'shoulder_abduction', 'unilateral', 'weight_reps', 'beginner', 'lengthened', 1, 2.5, 'https://www.youtube.com/watch?v=qitQHqNZbeM'),
  ('936642ff-7161-5395-90b9-fc428f932f42', 'band-lateral-raise', 'Seitheben mit Band', 'Band lateral raise', 'Seitliche Schulter ohne Hanteln: Band unter den Fuß, seitlich anheben. Der Widerstand steigt nach oben hin.', array['Mit einem Fuß auf das Bandende stellen, das andere Ende mit der Hand der Gegenseite greifen.', 'Arm leicht gebeugt neben dem Körper.', 'Arm seitlich bis etwa Schulterhöhe heben.', 'Langsam absenken, beide Seiten gleich oft.'], array['Schulter zieht zum Ohr', 'Band zu leicht'], array['Nach außen, nicht nach oben', 'Oben kurz halten'], 'isolation', 'shoulder_abduction', 'unilateral', 'bodyweight_reps', 'beginner', 'shortened', 1, 1, 'https://www.youtube.com/watch?v=aWZUEr7Jfx0'),
  ('f8edbc13-299d-5020-9ad2-5a6ab6185beb', 'reverse-pec-deck', 'Reverse Butterfly (Maschine)', 'Reverse pec deck', 'Isoliert die hintere Schulter – wichtig für runde Schultern von der Seite und eine aufrechte Haltung.', array['Mit der Brust zur Lehne setzen, Griffe auf Schulterhöhe.', 'Arme fast gestreckt, Daumen nach unten oder neutral.', 'Arme in einem Bogen nach hinten außen führen.', 'Langsam zurück nach vorne.'], array['Schulterblätter zu stark zusammenziehen (Rücken übernimmt)', 'Schwung'], array['Weit nach außen schieben', 'Schultern tief'], 'isolation', 'shoulder_horizontal_abduction', 'bilateral', 'weight_reps', 'beginner', 'shortened', 1, 2.5, 'https://www.youtube.com/watch?v=dC7jhEk-29A'),
  ('528a9c5c-5c77-5725-a15a-556decc5db2e', 'face-pull', 'Face Pulls', 'Face pull', 'Zug zum Gesicht für hintere Schulter und oberen Rücken. Gut für Schultergesundheit und Haltung.', array['Seil auf Stirnhöhe einhängen, mit beiden Händen im Obergriff fassen.', 'Einen Schritt zurück, Arme gestreckt.', 'Seil Richtung Gesicht ziehen, Ellbogen hoch und weit außen.', 'Hände am Ende neben die Ohren auseinanderziehen, dann langsam zurück.'], array['Ellbogen zu tief – wird zum Rudern', 'Oberkörper lehnt sich zurück'], array['Ellbogen hoch', 'Doppelbizeps-Pose am Ende'], 'isolation', 'shoulder_horizontal_abduction', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=V8dZ3pyiCBo'),
  ('8a846bf3-a8d3-596b-af54-a5df93a54860', 'bent-over-reverse-fly', 'Vorgebeugtes Seitheben (Kurzhantel)', 'Bent-over reverse fly', 'Hintere Schulter mit Kurzhanteln – die Alternative ohne Maschine.', array['Hüfte nach hinten schieben, Oberkörper fast waagerecht, Rücken gerade.', 'Hanteln hängen unter den Schultern, Arme leicht gebeugt.', 'Arme seitlich anheben, bis sie in einer Linie mit dem Körper sind.', 'Langsam absenken.'], array['Oberkörper richtet sich auf', 'Schwung'], array['Hanteln nach außen schieben', 'Nacken lang'], 'isolation', 'shoulder_horizontal_abduction', 'bilateral', 'weight_reps', 'beginner', 'shortened', 1, 1, 'https://www.youtube.com/watch?v=ttvfGg9d76c'),
  ('f53ead71-aa24-52e4-b928-73508414a357', 'band-pull-apart', 'Band Pull-Aparts', 'Band pull-apart', 'Hintere Schulter mit Widerstandsband – leicht, gelenkschonend und überall machbar.', array['Band schulterbreit vor der Brust greifen, Arme gestreckt.', 'Band auseinanderziehen, bis es die Brust berührt.', 'Kurz halten, dann langsam zurückführen.'], array['Arme beugen', 'Schultern zu den Ohren'], array['Arme lang', 'Brust zum Band'], 'isolation', 'shoulder_horizontal_abduction', 'bilateral', 'bodyweight_reps', 'beginner', 'shortened', 1, 1, 'https://www.youtube.com/watch?v=stwYTTPXubo'),
  ('d027ad9a-baa7-5b36-b191-994b8a1edbcc', 'pull-up', 'Klimmzug', 'Pull-up', 'Die Königsübung für einen breiten Rücken. Steigern über Wiederholungen und später Zusatzgewicht.', array['Stange etwas weiter als schulterbreit im Obergriff fassen, frei hängen.', 'Schultern nach unten ziehen, Bauch anspannen.', 'Hochziehen, bis das Kinn über der Stange ist – Ellbogen Richtung Hüfte.', 'Kontrolliert bis zur vollen Armstreckung absenken.'], array['Schwung aus den Beinen (Kipping)', 'Unten nicht ganz strecken'], array['Ellbogen in die Hosentaschen', 'Brust zur Stange'], 'compound', 'vertical_pull', 'bilateral', 'bodyweight_reps', 'intermediate', 'mid_range', 3, 2.5, 'https://www.youtube.com/watch?v=Hdc7Mw6BIEE'),
  ('11180ee1-a727-58d2-8834-8c6768c56aa0', 'lat-pulldown', 'Latziehen', 'Lat pulldown', 'Vertikales Ziehen am Kabel – frei dosierbar und ideal, solange Klimmzüge noch zu schwer sind.', array['Knie unter das Polster klemmen, Stange etwas weiter als schulterbreit greifen.', 'Oberkörper leicht zurückneigen, Brust heraus.', 'Stange zur oberen Brust ziehen, Ellbogen nach unten und hinten.', 'Langsam nach oben lassen, bis die Arme gestreckt und die Lats gedehnt sind.'], array['Stark zurücklehnen und reißen', 'Stange in den Nacken ziehen'], array['Ellbogen zur Hüfte', 'Oben richtig strecken'], 'compound', 'vertical_pull', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 2, 2.5, 'https://www.youtube.com/watch?v=CAwf7n6Luuc'),
  ('4eb75d16-8633-5619-8727-ba517150e468', 'band-lat-pulldown', 'Latziehen mit Band', 'Band lat pulldown', 'Latziehen zu Hause: Band oben verankern (z. B. an der Klimmzugstange oder Tür) und kniend ziehen.', array['Band hoch über dem Kopf verankern, davor knien.', 'Band mit gestreckten Armen greifen.', 'Ellbogen nach unten zur Hüfte ziehen.', 'Langsam zurück in die Streckung.'], array['Nur mit den Armen ziehen', 'Zu leichtes Band – weit weg vom Versagen'], array['Ellbogen runter', 'Brust raus'], 'compound', 'vertical_pull', 'bilateral', 'bodyweight_reps', 'beginner', 'shortened', 1, 1, 'https://www.youtube.com/watch?v=_97pmOC2tzE'),
  ('f1576423-9e63-5b1e-b239-533f1b534db3', 'barbell-row', 'Langhantelrudern vorgebeugt', 'Barbell bent-over row', 'Schwere Grundübung für den ganzen Rücken. Fordert auch den unteren Rücken stark.', array['Stange schulterbreit greifen, Hüfte nach hinten, Oberkörper etwa 45° vorgebeugt.', 'Rücken gerade, Knie leicht gebeugt.', 'Stange zum Bauchnabel ziehen, Ellbogen nah am Körper.', 'Kontrolliert absenken, ohne den Oberkörper aufzurichten.'], array['Runder Rücken', 'Oberkörper richtet sich mit jeder Wiederholung mehr auf'], array['Rücken flach wie ein Tisch', 'Ellbogen nach hinten'], 'compound', 'horizontal_pull', 'bilateral', 'weight_reps', 'intermediate', 'mid_range', 4, 2.5, 'https://www.youtube.com/watch?v=FWJR5Ve8bnQ'),
  ('3c098b60-afde-5c99-9e80-dbe1ddc4c366', 'one-arm-dumbbell-row', 'Einarmiges Kurzhantelrudern', 'One-arm dumbbell row', 'Einseitiges Rudern mit großem Bewegungsumfang. Entlastet den unteren Rücken durch die Abstützung.', array['Eine Hand und ein Knie auf der Bank abstützen, Rücken gerade.', 'Hantel hängt mit gestrecktem Arm unter der Schulter.', 'Hantel Richtung Hüfte ziehen, Ellbogen nah am Körper.', 'Langsam absenken, bis die Schulter nach vorne gedehnt ist.'], array['Oberkörper dreht sich auf', 'Hantel zur Brust statt zur Hüfte'], array['Ellbogen in die Hosentasche', 'Unten lang machen'], 'compound', 'horizontal_pull', 'unilateral', 'weight_reps', 'beginner', 'mid_range', 2, 2, 'https://www.youtube.com/watch?v=djKXLt7kv7Q'),
  ('fa0f2704-c9e0-5ade-b39d-c9b477cef418', 'seated-cable-row', 'Rudern am Kabel (sitzend)', 'Seated cable row', 'Kontrolliertes horizontales Ziehen mit konstanter Spannung – rückenschonend und gut dosierbar.', array['Füße auf die Plattform, Knie leicht gebeugt, Griff fassen.', 'Aufrecht sitzen, Brust heraus.', 'Griff zum Bauch ziehen, Schulterblätter zusammenführen.', 'Langsam nach vorne lassen, bis Arme gestreckt und Schulterblätter auseinander sind.'], array['Starkes Vor- und Zurückschwingen', 'Schultern ziehen hoch'], array['Brust stolz', 'Schulterblätter zusammen'], 'compound', 'horizontal_pull', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 2, 2.5, 'https://www.youtube.com/watch?v=GZbfZ033f74'),
  ('89402a27-c4b5-5e1e-8f1c-9ef3a747becf', 'chest-supported-dumbbell-row', 'Brustgestütztes Rudern (Kurzhantel)', 'Chest-supported dumbbell row', 'Rudern bäuchlings auf der Schrägbank – kein Schwung möglich, kaum Belastung für den unteren Rücken.', array['Bank auf etwa 30–45° stellen, bäuchlings darauf legen.', 'Hanteln hängen senkrecht nach unten.', 'Hanteln nach oben ziehen, Ellbogen etwa 45° vom Körper.', 'Langsam absenken.'], array['Brust löst sich von der Bank', 'Nur halbe Bewegung'], array['Brust auf der Bank', 'Ellbogen nach hinten oben'], 'compound', 'horizontal_pull', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2, 'https://www.youtube.com/watch?v=G6q02UC52xQ'),
  ('01d02d43-81d1-5abe-b3a5-720bf47b9c69', 'band-row', 'Rudern mit Band', 'Band row', 'Horizontales Ziehen mit Band – um die Füße gelegt oder an einem festen Punkt verankert.', array['Sitzend das Band um die Füße legen oder auf Brusthöhe verankern.', 'Aufrecht, Arme gestreckt.', 'Band zum Bauch ziehen, Schulterblätter zusammen.', 'Langsam zurück.'], array['Zurücklehnen statt ziehen', 'Band zu leicht'], array['Ellbogen nach hinten', 'Brust raus'], 'compound', 'horizontal_pull', 'bilateral', 'bodyweight_reps', 'beginner', 'shortened', 1, 1, 'https://www.youtube.com/watch?v=LSkyinhmA8k'),
  ('f04c5dbe-a888-54b6-9461-72317c3a4015', 'straight-arm-pulldown', 'Überzüge am Kabel (gestreckte Arme)', 'Straight-arm pulldown', 'Isoliert den Latissimus ohne Bizeps-Beteiligung. Gut, um den Rücken gezielt zu spüren.', array['Stange oder Seil oben einhängen, einen Schritt zurück, leicht vorbeugen.', 'Arme fast gestreckt über Kopfhöhe.', 'Stange im Bogen bis zu den Oberschenkeln ziehen.', 'Langsam nach oben in die Dehnung zurückführen.'], array['Arme beugen', 'Oberkörper pumpt mit'], array['Arme wie Hebel', 'Hände zu den Hosentaschen'], 'isolation', 'shoulder_extension', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=wcVDItawocI'),
  ('14b7da32-a13e-59b4-8b28-9f46448e2bf2', 'dumbbell-pullover', 'Kurzhantel-Pullover', 'Dumbbell pullover', 'Belastet den Latissimus stark in der gedehnten Position über dem Kopf.', array['Quer oder längs auf der Bank liegen, eine Hantel mit beiden Händen über der Brust.', 'Arme leicht gebeugt, Hantel im Bogen hinter den Kopf absenken.', 'Bis zur deutlichen Dehnung, ohne Schmerzen in der Schulter.', 'Im Bogen zurück über die Brust ziehen.'], array['Zu tief bei eingeschränkter Schulterbeweglichkeit', 'Arme stark beugen'], array['Mit den Ellbogen ziehen', 'Rippen unten halten'], 'isolation', 'shoulder_extension', 'bilateral', 'weight_reps', 'intermediate', 'lengthened', 1, 2, 'https://www.youtube.com/watch?v=Ydpy886udzo'),
  ('4d72096d-b955-5d11-8561-2689f732d8b7', 'ez-bar-curl', 'SZ-Curls', 'EZ-bar curl', 'Bizeps-Grundübung mit der gewinkelten SZ-Stange – angenehmer für die Handgelenke als die gerade Stange.', array['Aufrecht stehen, Stange an den inneren Winkeln im Untergriff fassen.', 'Ellbogen seitlich am Körper fixieren.', 'Stange nach oben curlen, ohne die Ellbogen nach vorne zu schieben.', 'Langsam bis zur vollen Streckung absenken.'], array['Schwung aus dem Rücken', 'Unten nicht ganz strecken'], array['Ellbogen bleiben stehen', 'Unten ganz lang'], 'isolation', 'elbow_flexion', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=aEscWJ3dS3w'),
  ('32a55632-15dd-5a63-8e2f-8360d313a587', 'dumbbell-curl', 'Kurzhantel-Curls', 'Dumbbell curl', 'Einfache Bizepsübung mit Supination (Handfläche dreht nach oben) für volle Bizepsarbeit.', array['Stehen, Hanteln seitlich, Handflächen zum Körper.', 'Beim Hochcurlen die Handfläche nach oben drehen.', 'Oben kurz anspannen.', 'Langsam bis zur vollen Streckung absenken.'], array['Abwechselnd mit Schwung', 'Ellbogen wandern nach vorne'], array['Kleiner Finger nach oben drehen', 'Langsam runter'], 'isolation', 'elbow_flexion', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2, 'https://www.youtube.com/watch?v=sAq_ocpRh_I'),
  ('ffeb10a0-479e-56a7-82c5-ddc300466ec8', 'incline-dumbbell-curl', 'Schrägbank-Curls', 'Incline dumbbell curl', 'Curls im Liegen auf der Schrägbank: Die Arme hängen hinter dem Körper und belasten den Bizeps in gedehnter Position.', array['Bank auf etwa 45–60°, zurücklehnen, Arme hängen senkrecht.', 'Hanteln curlen, Oberarme bleiben hinter dem Körper.', 'Oben kurz anspannen.', 'Ganz langsam bis zur vollen Dehnung absenken.'], array['Schultern rollen nach vorne', 'Zu schwer – Oberarme schwingen mit'], array['Arme hängen lassen', 'Dehnung spüren'], 'isolation', 'elbow_flexion', 'bilateral', 'weight_reps', 'beginner', 'lengthened', 1, 2, 'https://www.youtube.com/watch?v=soxrZlIl35U'),
  ('5aefb07c-cf1b-5c4a-be39-8fe48b3a0ae0', 'hammer-curl', 'Hammer-Curls', 'Hammer curl', 'Curls im neutralen Griff – trainieren zusätzlich Brachialis und Unterarm für dickere Arme.', array['Hanteln seitlich, Daumen zeigen nach vorne.', 'Hanteln curlen, Handgelenk bleibt neutral.', 'Oben kurz halten.', 'Langsam absenken.'], array['Schwung', 'Handgelenk knickt ab'], array['Daumen nach oben', 'Ellbogen ruhig'], 'isolation', 'elbow_flexion', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2, 'https://www.youtube.com/watch?v=zC3nLlEvin4'),
  ('f35331f9-b848-5161-9ae8-b9b301b7c7b6', 'cable-curl', 'Kabel-Curls', 'Cable curl', 'Curls mit konstanter Spannung über den ganzen Bewegungsweg – gut für Pump-Sätze.', array['Stange unten einhängen, im Untergriff fassen, einen kleinen Schritt zurück.', 'Ellbogen am Körper fixieren.', 'Hochcurlen und oben anspannen.', 'Langsam bis zur Streckung zurück.'], array['Oberkörper lehnt sich zurück', 'Ellbogen wandern'], array['Ellbogen festnageln', 'Langsam ablassen'], 'isolation', 'elbow_flexion', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=NFzTWp2qpiE'),
  ('cf3decf5-b9c4-5a8e-91cb-a38c7c53d324', 'band-curl', 'Bizeps-Curls mit Band', 'Band curl', 'Bizepstraining zu Hause: Band unter die Füße, Widerstand steigt nach oben hin.', array['Auf das Band stellen, Enden im Untergriff fassen.', 'Ellbogen am Körper, hochcurlen.', 'Oben anspannen, langsam zurück.'], array['Zu leichtes Band', 'Ellbogen nach vorne'], array['Oben richtig zusammendrücken', 'Kontrolliert zurück'], 'isolation', 'elbow_flexion', 'bilateral', 'bodyweight_reps', 'beginner', 'shortened', 1, 1, 'https://www.youtube.com/watch?v=AaA7Yj3zHiU'),
  ('4818f01d-9940-53a8-ba6b-081a33224ebc', 'overhead-cable-triceps-extension', 'Trizepsdrücken über Kopf (Kabel)', 'Overhead cable triceps extension', 'Dehnt den langen Trizepskopf maximal. Brachte in einer Studie etwa 1,4-mal so viel Trizepswachstum wie dieselbe Bewegung mit dem Arm neben dem Körper (Maeo et al. 2023).', array['Seil unten einhängen, mit dem Rücken zum Turm stellen, Seil über den Kopf nehmen.', 'Schrittstellung, leicht nach vorne lehnen, Oberarme neben dem Kopf.', 'Arme nach vorne oben strecken.', 'Langsam hinter den Kopf zurückführen, bis der Trizeps gedehnt ist.'], array['Ellbogen weit auseinander', 'Bewegung kommt aus der Schulter'], array['Ellbogen zeigen nach vorne', 'Tief in die Dehnung'], 'isolation', 'elbow_extension', 'bilateral', 'weight_reps', 'beginner', 'lengthened', 1, 2.5, 'https://www.youtube.com/watch?v=fYqswDVbJDg'),
  ('9316b2b4-518f-5112-8241-c884d2c0d28a', 'cable-triceps-pushdown', 'Trizepsdrücken am Kabel', 'Cable triceps pushdown', 'Einfache Trizepsübung, die vor allem die verkürzte Position trainiert. Gut als Ergänzung zur Überkopf-Variante.', array['Seil oder Stange oben einhängen, aufrecht davor stehen.', 'Ellbogen seitlich am Körper.', 'Nach unten drücken, bis die Arme gestreckt sind.', 'Langsam bis etwa 90° Beugung zurück.'], array['Ellbogen wandern nach vorne', 'Mit dem Oberkörper drücken'], array['Ellbogen festnageln', 'Unten auseinanderziehen (Seil)'], 'isolation', 'elbow_extension', 'bilateral', 'weight_reps', 'beginner', 'shortened', 1, 2.5, 'https://www.youtube.com/watch?v=_w-HpW70nSQ'),
  ('bd8c8135-cb18-5277-a1ef-09d9d54f8281', 'ez-skull-crusher', 'French Press / Skull Crusher (SZ)', 'EZ-bar skull crusher', 'Liegendes Trizepsdrücken mit starker Dehnung. Auf saubere, langsame Ausführung achten – die Ellbogen werden stark gefordert.', array['Auf der Bank liegen, SZ-Stange mit gestreckten Armen über der Stirn.', 'Oberarme leicht nach hinten geneigt.', 'Stange langsam hinter die Stirn absenken, nur die Ellbogen beugen.', 'Zurück in die Streckung drücken.'], array['Ellbogen gehen weit auseinander', 'Zu schwer und unkontrolliert'], array['Oberarme ruhig', 'Hinter den Kopf, nicht auf die Stirn'], 'isolation', 'elbow_extension', 'bilateral', 'weight_reps', 'intermediate', 'lengthened', 1, 2.5, 'https://www.youtube.com/watch?v=d_KZxkY_0cM'),
  ('a3846cb6-618b-546d-98d6-487e71f1b7f4', 'overhead-dumbbell-triceps-extension', 'Trizepsdrücken über Kopf (Kurzhantel)', 'Overhead dumbbell triceps extension', 'Überkopf-Trizepsübung ohne Kabelzug – dehnt den langen Kopf ebenfalls stark.', array['Sitzend oder stehend eine Hantel mit beiden Händen über den Kopf halten.', 'Oberarme neben dem Kopf.', 'Hantel hinter dem Kopf absenken, bis der Trizeps gedehnt ist.', 'Nach oben strecken.'], array['Ellbogen zeigen zur Seite', 'Hohlkreuz'], array['Ellbogen zur Decke', 'Rippen unten'], 'isolation', 'elbow_extension', 'bilateral', 'weight_reps', 'beginner', 'lengthened', 1, 2, 'https://www.youtube.com/watch?v=-Vyt2QdsR7E'),
  ('7ede4fba-a5c7-56d0-b244-f2d20d4639b8', 'close-grip-push-up', 'Enge Liegestütze', 'Close-grip push-up', 'Liegestütze mit enger Handstellung verlagern die Arbeit auf den Trizeps – Trizepstraining ohne Equipment.', array['Hände schulterbreit oder etwas enger aufsetzen, Körper gestreckt.', 'Ellbogen beim Absenken eng am Körper nach hinten führen.', 'Brust bis knapp über den Boden senken.', 'Hochdrücken, bis die Arme gestreckt sind.'], array['Ellbogen gehen nach außen', 'Hüfte hängt durch'], array['Ellbogen streifen die Rippen', 'Körper wie ein Brett'], 'compound', 'elbow_extension', 'bilateral', 'bodyweight_reps', 'beginner', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=G2mlaEfpEIM'),
  ('5ce59da1-284a-5395-b31b-ceb00638f72e', 'barbell-back-squat', 'Kniebeuge (Langhantel)', 'Barbell back squat', 'Grundübung für Beine und Gesäß. Hohe Last und hohe Gesamtermüdung – Technik geht vor Gewicht.', array['Stange auf dem oberen Rücken ablegen, aus dem Rack heben, Füße schulterbreit.', 'Tief einatmen, Bauch fest anspannen.', 'Hüfte und Knie gleichzeitig beugen, Knie in Richtung Zehen.', 'So tief wie technisch sauber möglich, mindestens Oberschenkel parallel.', 'Aus der Mitte des Fußes kraftvoll hochdrücken.'], array['Knie fallen nach innen', 'Fersen heben ab', 'Unterer Rücken rundet sich unten'], array['Boden wegdrücken', 'Knie nach außen'], 'compound', 'squat', 'bilateral', 'weight_reps', 'intermediate', 'lengthened', 4, 2.5, 'https://www.youtube.com/watch?v=SW_C1A-rejs'),
  ('4956ba53-13c7-5ac9-9719-0aa1143544bc', 'goblet-squat', 'Goblet Squat', 'Goblet squat', 'Kniebeuge mit einer Hantel vor der Brust – ideal zum Lernen und für tiefe, aufrechte Beugen.', array['Eine Hantel senkrecht vor der Brust halten, Füße etwas weiter als hüftbreit.', 'Oberkörper aufrecht, tief in die Hocke gehen.', 'Ellbogen zwischen den Knien.', 'Aus der Ferse hochdrücken.'], array['Oberkörper kippt nach vorne', 'Fersen heben ab'], array['Brust hoch', 'Zwischen die Beine setzen'], 'compound', 'squat', 'bilateral', 'weight_reps', 'beginner', 'lengthened', 2, 2, 'https://www.youtube.com/watch?v=CkFzgR55gho'),
  ('9c03f20e-c9fa-5432-828a-c84e7033b6e5', 'leg-press', 'Beinpresse', 'Leg press', 'Schweres Beintraining ohne Belastung der Wirbelsäule. Sehr gut, um die Oberschenkel nah ans Versagen zu bringen.', array['Rücken und Gesäß fest an die Lehne, Füße schulterbreit mittig auf die Platte.', 'Sicherung lösen, Platte langsam herablassen.', 'So tief, wie das Gesäß an der Lehne bleibt.', 'Durch die ganze Fußsohle zurückdrücken, Knie oben nicht durchstrecken.'], array['Gesäß rollt unten von der Lehne', 'Knie oben überstrecken'], array['Gesäß bleibt unten', 'Tief, aber kontrolliert'], 'compound', 'squat', 'bilateral', 'weight_reps', 'beginner', 'lengthened', 3, 5, 'https://www.youtube.com/watch?v=B6rGDcfyPto'),
  ('ef629dfd-5efe-55ae-9fa1-950e20697d27', 'bulgarian-split-squat', 'Bulgarische Kniebeuge', 'Bulgarian split squat', 'Einbeinige Kniebeuge mit erhöhtem hinteren Fuß. Trainiert Quadrizeps und Gesäß in tiefer Dehnung. Mit oder ohne Kurzhanteln.', array['Mit dem Rücken zur Bank stehen, einen Fuß hinten auf die Bank legen.', 'Vorderer Fuß etwa einen großen Schritt vor der Bank.', 'Senkrecht nach unten sinken, bis der vordere Oberschenkel etwa parallel ist.', 'Über das vordere Bein hochdrücken.'], array['Vorderer Fuß zu nah an der Bank', 'Knie fällt nach innen'], array['Nach unten, nicht nach vorne', 'Gewicht auf dem vorderen Fuß'], 'compound', 'lunge', 'unilateral', 'weight_reps', 'intermediate', 'lengthened', 3, 2, 'https://www.youtube.com/watch?v=SkNsa3eBwLA'),
  ('1a860366-e2a4-5722-9ade-df474f5b3204', 'walking-lunge', 'Ausfallschritte gehend', 'Walking lunge', 'Ausfallschritte in Bewegung – braucht kein Equipment, Kurzhanteln sind optional.', array['Aufrecht stehen, großen Schritt nach vorne machen.', 'Hinteres Knie bis knapp über den Boden senken.', 'Über das vordere Bein hochdrücken und den nächsten Schritt machen.', 'Pro Bein gleich viele Wiederholungen zählen.'], array['Zu kurze Schritte', 'Oberkörper kippt nach vorne'], array['Großer Schritt', 'Hinteres Knie Richtung Boden'], 'compound', 'lunge', 'unilateral', 'weight_reps', 'beginner', 'lengthened', 3, 2, 'https://www.youtube.com/watch?v=Pbmj6xPo-Hw'),
  ('6d4e4ddf-510c-5d3f-949f-e6278a1f9e21', 'deadlift', 'Kreuzheben (konventionell)', 'Conventional deadlift', 'Ganzkörper-Grundübung für die gesamte Rückseite. Sehr hohe Gesamtermüdung – deshalb mit etwas mehr Abstand zum Versagen trainieren.', array['Füße hüftbreit, Stange über der Fußmitte.', 'Hüfte nach hinten beugen, Stange schulterbreit greifen.', 'Rücken gerade, Brust heraus, Spannung aufbauen („Durchhang aus der Stange ziehen“).', 'Stange nah am Körper hochziehen, Hüfte und Knie gleichzeitig strecken.', 'Kontrolliert in gleicher Bahn absetzen.'], array['Runder Rücken', 'Stange entfernt sich vom Körper', 'Oben überstrecken'], array['Boden wegschieben', 'Stange am Schienbein entlang'], 'compound', 'hinge', 'bilateral', 'weight_reps', 'intermediate', 'mid_range', 5, 5, 'https://www.youtube.com/watch?v=VL5Ab0T07e4'),
  ('4d1aa5f2-b601-529a-9f27-0df44f37d037', 'romanian-deadlift', 'Rumänisches Kreuzheben (Langhantel)', 'Romanian deadlift', 'Hüftbeuge mit fast gestreckten Beinen – belastet die Beinbeuger stark in gedehnter Position.', array['Stange aufrecht stehend vor den Oberschenkeln halten, Knie leicht gebeugt.', 'Hüfte nach hinten schieben, Stange gleitet an den Beinen nach unten.', 'Rücken bleibt gerade – so tief, bis die Beinbeuger stark gedehnt sind.', 'Hüfte nach vorne schieben und aufrichten.'], array['Runder Rücken', 'Knie beugen sich immer mehr (wird zur Kniebeuge)'], array['Gesäß an die Wand hinter dir', 'Stange am Bein'], 'compound', 'hinge', 'bilateral', 'weight_reps', 'intermediate', 'lengthened', 4, 2.5, 'https://www.youtube.com/watch?v=_oyxCn2iSjU'),
  ('02335235-c15a-570e-abdc-f254fbac5c47', 'dumbbell-romanian-deadlift', 'Rumänisches Kreuzheben (Kurzhantel)', 'Dumbbell Romanian deadlift', 'Wie die Langhantel-Variante, aber leichter zu lernen und zu Hause machbar.', array['Hanteln vor den Oberschenkeln, Knie leicht gebeugt.', 'Hüfte nach hinten schieben, Hanteln nah an den Beinen nach unten führen.', 'Rücken gerade, bis die Beinbeuger gedehnt sind.', 'Hüfte nach vorne, aufrichten.'], array['Runder Rücken', 'Hanteln weit vor dem Körper'], array['Hüfte nach hinten', 'Dehnung in den Oberschenkelrückseiten'], 'compound', 'hinge', 'bilateral', 'weight_reps', 'beginner', 'lengthened', 3, 2, 'https://www.youtube.com/watch?v=hQgFixeXdZo'),
  ('20662e67-60fc-5d6a-b16c-cabc6c6a8ba6', 'single-leg-romanian-deadlift', 'Einbeiniges Rumänisches Kreuzheben', 'Single-leg Romanian deadlift', 'Einbeinige Hüftbeuge für Beinbeuger und Gesäß. Schon mit Körpergewicht fordernd, Kurzhantel optional.', array['Auf einem Bein stehen, Knie leicht gebeugt.', 'Oberkörper nach vorne neigen, das freie Bein nach hinten strecken.', 'Rücken gerade, bis der hintere Oberschenkel gedehnt ist.', 'Über die Hüfte aufrichten, beide Seiten gleich oft.'], array['Hüfte dreht sich auf', 'Runder Rücken'], array['Hüfte bleibt waagerecht', 'Wie eine Waage kippen'], 'compound', 'hinge', 'unilateral', 'weight_reps', 'intermediate', 'lengthened', 2, 2, 'https://www.youtube.com/watch?v=Zfr6wizR8rs'),
  ('3e8bff2b-2bb1-534a-9588-d25d030943a0', 'back-extension', 'Rückenstrecken 45° (Hyperextension)', '45° back extension', 'Hüftstreckung auf der Hyperextension-Bank. Mit leicht rundem oberen Rücken betont sie das Gesäß.', array['Polster knapp unter die Hüftknochen einstellen, Füße fixieren.', 'Oberkörper aus der Hüfte nach unten beugen.', 'Über die Hüfte nach oben strecken, bis der Körper eine Linie bildet.', 'Nicht ins Hohlkreuz überstrecken.'], array['Oben überstrecken', 'Bewegung nur aus dem unteren Rücken'], array['Gesäß anspannen', 'Aus der Hüfte klappen'], 'compound', 'hip_extension', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 2, 2.5, 'https://www.youtube.com/watch?v=k6LyPhGRV-o'),
  ('b03d9554-e5ec-50c0-817d-aa34bd59eb0b', 'barbell-hip-thrust', 'Hip Thrust (Langhantel)', 'Barbell hip thrust', 'Die effektivste Last-Übung für das Gesäß in der verkürzten Position.', array['Oberen Rücken an die Bankkante lehnen, Stange (mit Polster) über der Hüfte.', 'Füße hüftbreit, Schienbeine oben senkrecht.', 'Hüfte nach oben drücken, bis der Oberkörper waagerecht ist.', 'Oben das Gesäß fest anspannen, langsam absenken.'], array['Hohlkreuz statt Hüftstreckung', 'Füße zu weit vorne'], array['Kinn zur Brust', 'Gesäß zusammenpressen'], 'compound', 'hip_extension', 'bilateral', 'weight_reps', 'beginner', 'shortened', 2, 2.5, 'https://www.youtube.com/watch?v=Zp26q4BY5HE'),
  ('3dc0d583-71af-5467-9882-1b05c4cd5167', 'glute-bridge', 'Glute Bridge', 'Glute bridge', 'Hüftheben vom Boden – Gesäßtraining ohne Equipment, Gewicht auf der Hüfte optional.', array['Rückenlage, Füße hüftbreit nah am Gesäß.', 'Hüfte nach oben drücken, bis Knie, Hüfte und Schultern eine Linie bilden.', 'Oben 1–2 Sekunden halten.', 'Langsam absenken.'], array['Hohlkreuz', 'Druck über die Zehen'], array['Über die Fersen drücken', 'Oben anspannen'], 'isolation', 'hip_extension', 'bilateral', 'bodyweight_reps', 'beginner', 'shortened', 1, 2.5, 'https://www.youtube.com/watch?v=wPM8icPu6H8'),
  ('427d89d8-0838-532c-82b9-27f4378df6f5', 'seated-leg-curl', 'Beinbeuger sitzend (Maschine)', 'Seated leg curl', 'Im Sitzen sind die Beinbeuger stärker gedehnt. Brachte deutlich mehr Wachstum als die liegende Variante (Maeo et al. 2021).', array['Kniegelenk auf Höhe der Maschinenachse, Polster über den Knöcheln, Oberschenkel fixieren.', 'Leicht nach vorne lehnen für mehr Dehnung.', 'Unterschenkel nach unten hinten beugen.', 'Langsam zurück bis zur vollen Streckung.'], array['Gesäß hebt ab', 'Unten nicht ganz strecken'], array['Fersen zum Gesäß', 'Oben ganz strecken'], 'isolation', 'knee_flexion', 'bilateral', 'weight_reps', 'beginner', 'lengthened', 1, 2.5, 'https://www.youtube.com/watch?v=ELOCsoDSmrg'),
  ('c312470d-7837-5683-93bb-8dd99f8ddce7', 'lying-leg-curl', 'Beinbeuger liegend (Maschine)', 'Lying leg curl', 'Beinbeuger-Isolation in Bauchlage. Wenn möglich die sitzende Variante bevorzugen.', array['Bäuchlings auf die Maschine, Knie knapp über der Polsterkante.', 'Hüfte fest auf das Polster drücken.', 'Fersen Richtung Gesäß beugen.', 'Langsam bis zur Streckung zurück.'], array['Hüfte hebt ab', 'Schwung'], array['Hüfte runter', 'Langsam ablassen'], 'isolation', 'knee_flexion', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=jxctD6fL_FQ'),
  ('657ad933-dec9-5a96-a818-8c426b7b7f9e', 'nordic-hamstring-curl', 'Nordic Curls', 'Nordic hamstring curl', 'Sehr fordernde Beinbeuger-Übung mit Körpergewicht, vor allem in der nachgebenden Phase. Füße brauchen eine feste Verankerung.', array['Kniend, Fersen fest verankern (Partner, Sofa, Hantelstange).', 'Körper gerade von Knie bis Kopf.', 'Sich so langsam wie möglich nach vorne sinken lassen.', 'Mit den Händen abfangen und wieder hochdrücken.'], array['Hüfte knickt ein', 'Zu schnell fallen lassen'], array['Körper wie ein Brett', 'So langsam wie möglich'], 'isolation', 'knee_flexion', 'bilateral', 'bodyweight_reps', 'advanced', 'lengthened', 2, 2.5, 'https://www.youtube.com/watch?v=6NCN6kOagfY'),
  ('176b7930-e25e-5ca1-9f87-5f52b364fae1', 'leg-extension', 'Beinstrecker (Maschine)', 'Leg extension', 'Isoliert den Quadrizeps. Gut, um die Oberschenkel ohne Belastung des Rückens nah ans Versagen zu bringen.', array['Kniegelenk auf Höhe der Maschinenachse, Polster über den Knöcheln.', 'Griffe fassen, Gesäß bleibt auf dem Sitz.', 'Beine bis zur Streckung heben, oben kurz anspannen.', 'Langsam bis zur vollen Beugung absenken.'], array['Gewicht fallen lassen', 'Gesäß hebt ab'], array['Oben zusammendrücken', 'Unten tief'], 'isolation', 'knee_extension', 'bilateral', 'weight_reps', 'beginner', 'shortened', 1, 2.5, 'https://www.youtube.com/watch?v=ljO4jkwv8wQ'),
  ('99d16e26-4194-5d1b-b720-445a27746e24', 'hip-abduction-machine', 'Abduktoren-Maschine', 'Hip abduction machine', 'Trainiert den seitlichen Gesäßmuskel – formt die obere, seitliche Gesäßpartie.', array['Polster außen an den Knien, aufrecht oder leicht vorgeneigt sitzen.', 'Beine gegen den Widerstand nach außen drücken.', 'Kurz halten.', 'Langsam zurück.'], array['Schwung', 'Gewicht knallt zurück'], array['Knie nach außen', 'Langsam schließen'], 'isolation', 'hip_abduction', 'bilateral', 'weight_reps', 'beginner', 'shortened', 1, 2.5, 'https://www.youtube.com/watch?v=KvH0JkygU74'),
  ('39e356a4-52ca-5fa6-a579-002ae6cd5d4c', 'hip-adduction-machine', 'Adduktoren-Maschine', 'Hip adduction machine', 'Trainiert die Oberschenkel-Innenseite. Optional – die Adduktoren arbeiten bei Kniebeugen bereits mit.', array['Polster innen an den Knien, Beine geöffnet.', 'Beine gegen den Widerstand zusammenführen.', 'Kurz halten.', 'Langsam bis zur Dehnung öffnen.'], array['Zu weite Startposition bei Leistenbeschwerden', 'Schwung'], array['Kontrolliert schließen', 'Dehnung langsam'], 'isolation', 'hip_adduction', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=GmRSV_n2E_0'),
  ('81aabff1-8456-5962-bc84-3255f334f437', 'standing-calf-raise', 'Wadenheben stehend (Maschine)', 'Standing calf raise', 'Waden mit gestrecktem Knie. Die tiefe Dehnung unten ist entscheidend: Teilbewegungen in der Dehnung brachten mehr Wachstum als die volle Bewegung (Kassiano et al. 2023).', array['Schulterpolster einstellen, Fußballen auf die Kante.', 'Knie gestreckt, Fersen so tief wie möglich absenken.', 'Unten 1–2 Sekunden in der Dehnung halten.', 'Auf die Zehenspitzen hochdrücken.'], array['Federn ohne Pause', 'Nur obere Hälfte der Bewegung'], array['Unten Pause', 'Tief runter'], 'isolation', 'ankle_plantarflexion', 'bilateral', 'weight_reps', 'beginner', 'lengthened', 1, 5, 'https://www.youtube.com/watch?v=30ygzcJw4v4'),
  ('33c85844-000a-571b-bff8-ef41287e56e8', 'leg-press-calf-raise', 'Wadenheben an der Beinpresse', 'Leg press calf raise', 'Wadenheben ohne eigene Maschine. Fußballen am unteren Plattenrand.', array['Fußballen am unteren Rand der Platte, Beine fast gestreckt.', 'Sicherung eingelegt lassen, falls die Maschine das erlaubt.', 'Fersen tief Richtung Körper sinken lassen, kurz halten.', 'Platte mit den Fußballen wegdrücken.'], array['Knie beugen', 'Zu kleine Bewegung'], array['Dehnung halten', 'Knie bleiben gestreckt'], 'isolation', 'ankle_plantarflexion', 'bilateral', 'weight_reps', 'beginner', 'lengthened', 1, 5, 'https://www.youtube.com/watch?v=M4FojyRAcuE'),
  ('3cd54f6d-87a7-5b57-9df2-989623f9873d', 'single-leg-calf-raise', 'Einbeiniges Wadenheben (Stufe)', 'Single-leg calf raise', 'Wadentraining auf einer Treppenstufe – mit Körpergewicht schon fordernd, Kurzhantel optional.', array['Mit dem Fußballen eines Beins auf eine Stufe stellen, festhalten.', 'Ferse so tief wie möglich absenken und kurz halten.', 'Auf die Zehenspitze hochdrücken.', 'Beide Seiten gleich oft.'], array['Federn', 'Knie beugen'], array['Tief in die Dehnung', 'Oben kurz halten'], 'isolation', 'ankle_plantarflexion', 'unilateral', 'weight_reps', 'beginner', 'lengthened', 1, 2, 'https://www.youtube.com/watch?v=ORT4oJ_R8Qs'),
  ('7e1d74e1-8d37-536b-9dbb-27d9c1c1f88d', 'cable-crunch', 'Kabel-Crunches', 'Cable crunch', 'Bauchtraining mit Zusatzlast – wie andere Muskeln über Gewicht steigerbar.', array['Seil oben einhängen, davor knien, Seil neben dem Kopf halten.', 'Hüfte bleibt ruhig.', 'Oberkörper einrollen, Ellbogen Richtung Knie.', 'Langsam aufrollen.'], array['Bewegung aus der Hüfte statt Einrollen', 'Mit den Armen ziehen'], array['Rippen zum Becken', 'Rund machen'], 'isolation', 'core_flexion', 'bilateral', 'weight_reps', 'beginner', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=3qjoXDTuyOE'),
  ('303c5f0e-1dfb-508e-a3cc-7186d1a489f5', 'hanging-leg-raise', 'Hängendes Beinheben', 'Hanging leg raise', 'Anspruchsvolle Bauchübung an der Klimmzugstange. Becken am Ende nach oben einrollen.', array['An der Stange hängen, Schultern aktiv.', 'Beine (gebeugt oder gestreckt) nach oben heben.', 'Becken am Ende nach oben einrollen.', 'Langsam absenken, ohne zu schwingen.'], array['Schwung', 'Nur Hüftbeuger, kein Einrollen'], array['Becken einrollen', 'Langsam runter'], 'isolation', 'core_flexion', 'bilateral', 'bodyweight_reps', 'intermediate', 'mid_range', 1, 2.5, 'https://www.youtube.com/watch?v=X-ACS9vpRyU'),
  ('79c24a36-2697-582c-aa29-e403d0113017', 'plank', 'Unterarmstütz (Plank)', 'Plank', 'Statische Rumpfstabilität. Gemessen wird die Zeit.', array['Unterarme unter den Schultern, Körper gestreckt auf den Zehen.', 'Gesäß und Bauch anspannen, Becken leicht einrollen.', 'Position halten, ruhig weiteratmen.'], array['Hüfte hängt durch', 'Gesäß zu hoch'], array['Körper wie ein Brett', 'Ellbogen zu den Zehen ziehen'], 'isolation', 'core_anti_extension', 'bilateral', 'duration', 'beginner', null, 1, 2.5, 'https://www.youtube.com/watch?v=pSHjTRCQxIw'),
  ('d4266a0a-04e6-5541-98e4-41bc6ae08421', 'pallof-press', 'Pallof Press', 'Pallof press', 'Anti-Rotation: Der Rumpf hält gegen den seitlichen Zug. Gut für seitliche Bauchmuskeln und Stabilität.', array['Kabel auf Brusthöhe, seitlich zum Turm stellen, Griff mit beiden Händen vor der Brust.', 'Arme nach vorne strecken, ohne dass der Oberkörper mitdreht.', 'Kurz halten, zurück zur Brust.', 'Beide Seiten gleich oft.'], array['Oberkörper dreht zum Kabel', 'Zu nah am Turm'], array['Nicht mitdrehen', 'Hüfte nach vorne'], 'isolation', 'core_rotation', 'unilateral', 'weight_reps', 'beginner', null, 1, 2.5, 'https://www.youtube.com/watch?v=5_8d8vHgZvU'),
  ('a71f066f-6c63-5068-b4f0-9ae7b48de65f', 'crunch', 'Crunch', 'Crunch', 'Bauchtraining ohne Equipment. Für mehr Widerstand eine Hantel auf die Brust legen.', array['Rückenlage, Beine angewinkelt.', 'Hände an die Schläfen oder vor die Brust.', 'Oberen Rücken einrollen, bis die Schulterblätter abheben.', 'Langsam abrollen.'], array['Am Nacken ziehen', 'Hochschwingen'], array['Rippen zum Becken', 'Langsam ab'], 'isolation', 'core_flexion', 'bilateral', 'bodyweight_reps', 'beginner', 'shortened', 1, 2.5, 'https://www.youtube.com/watch?v=NGRKFMKhF8s')
