  ('3dc19a82-57d7-5647-b477-c85337a0b80b', 'Baz-Valle, Fontes-Villalba & Santos-Concejero 2021', 'Total Number of Sets as a Training Volume Quantification Method for Muscle Hypertrophy: A Systematic Review', 'Journal of Strength and Conditioning Research', 2021, '10.1519/JSC.0000000000002776', 'systematic_review'),
