  ('9e6c1caf-6e5a-59e2-bb44-73ffa8436162', 'Bickel, Cross & Bamman 2011', 'Exercise Dosing to Retain Resistance Training Adaptations in Young and Older Adults', 'Medicine & Science in Sports & Exercise', 2011, '10.1249/MSS.0b013e318207c15d', 'rct'),
  ('5e0582b3-1717-535d-9b23-c57347694272', 'Scarpelli et al. 2022', 'Muscle Hypertrophy Response Is Affected by Previous Resistance Training Volume in Trained Individuals', 'Journal of Strength and Conditioning Research', 2022, '10.1519/JSC.0000000000003558', 'rct'),
  ('51986b2f-8a70-50a9-bc72-3983a66f6afe', 'Schoenfeld, Ogborn & Krieger 2016', 'Effects of Resistance Training Frequency on Measures of Muscle Hypertrophy: A Systematic Review and Meta-Analysis', 'Sports Medicine', 2016, '10.1007/s40279-016-0543-8', 'meta_analysis'),
