  ('a36dbf65-ab1e-5d0c-8dea-85899bf7aac3', 'Refalo et al. 2023', 'Influence of Resistance Training Proximity-to-Failure on Skeletal Muscle Hypertrophy: A Systematic Review with Meta-analysis', 'Sports Medicine', 2023, '10.1007/s40279-022-01784-y', 'meta_analysis'),
  ('a434717d-8cc6-5dc4-be99-0a1eebda7d56', 'Robinson et al. 2024', 'Exploring the Dose–Response Relationship Between Estimated Resistance Training Proximity to Failure, Strength Gain, and Muscle Hypertrophy: A Series of Meta-Regressions', 'Sports Medicine', 2024, '10.1007/s40279-024-02069-2', 'meta_analysis'),
  ('63728758-8eae-5c32-93a2-e3da790b71bc', 'Schoenfeld, Ogborn & Krieger 2015', 'Effect of Repetition Duration During Resistance Training on Muscle Hypertrophy: A Systematic Review and Meta-Analysis', 'Sports Medicine', 2015, '10.1007/s40279-015-0304-0', 'meta_analysis'),
  ('2bc51813-be19-5124-a838-528b34bfdc2e', 'Zourdos et al. 2016', 'Novel Resistance Training–Specific Rating of Perceived Exertion Scale Measuring Repetitions in Reserve', 'Journal of Strength and Conditioning Research', 2016, '10.1519/JSC.0000000000001049', 'observational'),
  ('99544ba2-2cb6-5404-8575-93cbc003ffdd', 'Helms, Cronin, Storey & Zourdos 2016', 'Application of the Repetitions in Reserve-Based Rating of Perceived Exertion Scale for Resistance Training', 'Strength and Conditioning Journal', 2016, '10.1519/SSC.0000000000000218', 'narrative_review'),
  ('99db360d-b810-5970-860e-f070b2e4d02b', 'Helms et al. 2018', 'RPE vs. Percentage 1RM Loading in Periodized Programs Matched for Sets and Repetitions', 'Frontiers in Physiology', 2018, '10.3389/fphys.2018.00247', 'rct'),
  ('e8fbf79f-ef0e-5e1a-b3eb-dc648fd4dbc8', 'Graham & Cleather 2021', 'Autoregulation by "Repetitions in Reserve" Leads to Greater Improvements in Strength Over a 12-Week Training Program Than Fixed Loading', 'Journal of Strength and Conditioning Research', 2021, '10.1519/JSC.0000000000003164', 'rct'),
  ('975dffab-15cd-59c8-b8ba-a70ebb5beca2', 'Plotkin et al. 2022', 'Progressive overload without progressing load? The effects of load or repetition progression on muscular adaptations', 'PeerJ', 2022, '10.7717/peerj.14142', 'rct'),
  ('6a30aab3-a886-590c-b460-85c9a1b43dfd', 'Schoenfeld et al. 2016', 'Longer Interset Rest Periods Enhance Muscle Strength and Hypertrophy in Resistance-Trained Men', 'Journal of Strength and Conditioning Research', 2016, '10.1519/JSC.0000000000001272', 'rct'),
  ('682ab56b-a280-5dd6-9fc1-011d01c253bb', 'Grgic et al. 2018', 'Effects of Rest Interval Duration in Resistance Training on Measures of Muscular Strength: A Systematic Review', 'Sports Medicine', 2018, '10.1007/s40279-017-0788-x', 'systematic_review'),
  ('b2086de5-abcf-500f-8795-1854ad08d966', 'Singer et al. 2024', 'Give it a rest: a systematic review with Bayesian meta-analysis on the effect of inter-set rest interval duration on muscle hypertrophy', 'Frontiers in Sports and Active Living', 2024, '10.3389/fspor.2024.1429789', 'meta_analysis'),
  ('d96de9c5-3132-5d98-b0d8-939db860c85c', 'Wackerhage et al. 2019', 'Stimuli and sensors that initiate skeletal muscle hypertrophy following resistance exercise', 'Journal of Applied Physiology', 2019, '10.1152/japplphysiol.00685.2018', 'narrative_review'),
  ('6b332b71-9928-5a13-9fbc-bd3dccc6569f', 'Schoenfeld & Contreras 2014', 'The Muscle Pump: Potential Mechanisms and Applications for Enhancing Hypertrophic Adaptations', 'Strength and Conditioning Journal', 2014, null, 'narrative_review'),
  ('f3408aae-c5cb-5b34-81e4-5dc0552cdf73', 'Sødal et al. 2023', 'Effects of Drop Sets on Skeletal Muscle Hypertrophy: A Systematic Review and Meta-analysis', 'Sports Medicine – Open', 2023, '10.1186/s40798-023-00620-5', 'meta_analysis'),
  ('bcded3e4-b9e0-5538-a6ae-53bf77294c12', 'Prestes et al. 2019', 'Strength and Muscular Adaptations After 6 Weeks of Rest-Pause vs. Traditional Multiple-Sets Resistance Training in Trained Subjects', 'Journal of Strength and Conditioning Research', 2019, '10.1519/JSC.0000000000001923', 'rct'),
  ('ca7fb4f6-1be2-5855-b730-e3e348e4911e', 'Maeo et al. 2021', 'Greater Hamstrings Muscle Hypertrophy but Similar Damage Protection after Training at Long versus Short Muscle Lengths', 'Medicine & Science in Sports & Exercise', 2021, '10.1249/MSS.0000000000002523', 'rct'),
  ('de282ca0-a2b2-5d8a-876f-10989c4eec7b', 'Maeo et al. 2023', 'Triceps brachii hypertrophy is substantially greater after elbow extension training performed in the overhead versus neutral arm position', 'European Journal of Sport Science', 2023, '10.1080/17461391.2022.2100279', 'rct'),
  ('7e185385-e07d-5fa0-a99c-bc92b9ffcc65', 'Pedrosa et al. 2022', 'Partial range of motion training elicits favorable improvements in muscular adaptations when carried out at long muscle lengths', 'European Journal of Sport Science', 2022, '10.1080/17461391.2021.1927199', 'rct'),
  ('d782a723-d6c5-5a5d-837f-8858ef6c0cab', 'Wolf et al. 2023', 'Partial Vs Full Range of Motion Resistance Training: A Systematic Review and Meta-Analysis', 'International Journal of Strength and Conditioning', 2023, '10.47206/ijsc.v3i1.182', 'meta_analysis'),
  ('b988bf0e-15e3-58cf-8f31-ae8ed94c37ff', 'Kassiano et al. 2023', 'Greater Gastrocnemius Muscle Hypertrophy After Partial Range of Motion Training Performed at Long Muscle Lengths', 'Journal of Strength and Conditioning Research', 2023, '10.1519/JSC.0000000000004460', 'rct'),
  ('1f4175be-5953-5457-b769-e8322e68abb6', 'Schoenfeld et al. 2018', 'Differential effects of attentional focus strategies during long-term resistance training', 'European Journal of Sport Science', 2018, '10.1080/17461391.2018.1447020', 'rct'),
  ('5f1ab6b6-9848-5c6b-9d82-373b60184f63', 'Kassiano et al. 2022', 'Does Varying Resistance Exercises Promote Superior Muscle Hypertrophy and Strength Gains? A Systematic Review', 'Journal of Strength and Conditioning Research', 2022, '10.1519/JSC.0000000000004258', 'systematic_review'),
  ('3b7708e0-9725-57d5-8d82-dd27ed5bbe75', 'Baz-Valle et al. 2019', 'The effects of exercise variation in muscle thickness, maximal strength and motivation in resistance trained men', 'PLoS ONE', 2019, '10.1371/journal.pone.0226989', 'rct'),
  ('884afde2-5b61-52e2-a26d-7ba9d09a8554', 'Coleman et al. 2024', 'Gaining more from doing less? The effects of a one-week deload period during supervised resistance training on muscular adaptations', 'PeerJ', 2024, '10.7717/peerj.16777', 'rct'),
  ('15b25b1c-11f2-583b-8f1e-61e2e421dfaa', 'Rogerson et al. 2024', 'Deloading Practices in Strength and Physique Sports: A Cross-sectional Survey', 'Sports Medicine – Open', 2024, '10.1186/s40798-024-00691-y', 'observational')
insert into public.scientific_guidelines (id, key, category, scope_goal, scope_experience, scope_mechanic, scope_muscle_group_id, scope_movement_pattern, scope_exercise_id, min_value, max_value, unit, title, message, rationale, severity, contexts, evidence_grade, priority, is_active) values
  ('2d693cd0-8f74-5cd4-b534-fe37928391dc', 'rep_range.hypertrophy', 'rep_range', 'hypertrophy', null, null, null, null, null, 6, 12, 'reps', 'Wiederholungsbereich', '{min}–{max} Wiederholungen pro Satz', 'Muskeln wachsen über ein breites Spektrum von etwa 6 bis 30 Wiederholungen ähnlich gut – entscheidend ist, nah ans Muskelversagen zu gehen. 6–12 ist bei Grundübungen zeiteffizient und gut steuerbar.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'strong', 0, true),
  ('8cb620f7-9a64-57ef-b06b-289718f9415d', 'rep_range.hypertrophy.isolation', 'rep_range', 'hypertrophy', null, 'isolation', null, null, null, 10, 20, 'reps', 'Wiederholungsbereich', '{min}–{max} Wiederholungen pro Satz', 'Bei Isolationsübungen bringen höhere Wiederholungszahlen das gleiche Wachstum, schonen die Gelenke und sorgen für mehr Pump.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('9d11bd42-5cd1-59ef-af86-7a88b88182b8', 'rep_range.hypertrophy.beginner.compound', 'rep_range', 'hypertrophy', 'beginner', 'compound', null, null, null, 8, 12, 'reps', 'Wiederholungsbereich', '{min}–{max} Wiederholungen pro Satz', 'Für Einsteiger empfehlen Positionspapiere moderate Lasten (8–12 Wiederholungen): genug Reiz, um zu wachsen, und Zeit, die Technik zu festigen.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('b94679c4-922d-5e51-83bb-43eae17895d8', 'rep_range.strength', 'rep_range', 'strength', null, null, null, null, null, 6, 12, 'reps', 'Wiederholungsbereich', '{min}–{max} Wiederholungen pro Satz', 'Ergänzungsübungen im Kraftfokus dienen dem Muskelaufbau und der Stabilität – moderate Wiederholungszahlen reichen.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('14a90ead-5ae3-56a8-ae1d-4d230d7d566e', 'rep_range.strength.compound', 'rep_range', 'strength', null, 'compound', null, null, null, 3, 6, 'reps', 'Wiederholungsbereich', '{min}–{max} schwere Wiederholungen', 'Für Maximalkraft sind schwere Lasten im niedrigen Wiederholungsbereich überlegen.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'strong', 0, true),
  ('6ff8d24f-5fdb-5d0e-85eb-69b5e22fe972', 'rep_range.strength.beginner.compound', 'rep_range', 'strength', 'beginner', 'compound', null, null, null, 6, 10, 'reps', 'Wiederholungsbereich', '{min}–{max} Wiederholungen pro Satz', 'Einsteiger werden schon mit moderaten Lasten stärker und lernen die Technik sicherer, bevor es schwer wird.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('90bd7d62-f7b1-5e86-a8b9-9e3ede8a3969', 'rep_range.endurance', 'rep_range', 'endurance', null, null, null, null, null, 15, 25, 'reps', 'Wiederholungsbereich', '{min}–{max} Wiederholungen pro Satz', 'Kraftausdauer verbessert sich am stärksten mit leichten bis moderaten Lasten und hohen Wiederholungszahlen.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('4198b07f-b290-50c7-9e9d-90ecfe8356ed', 'rir.hypertrophy', 'proximity_to_failure', 'hypertrophy', null, null, null, null, null, 0, 3, 'rir', 'Anstrengung', 'Lass {min}–{max} Wiederholungen im Tank', 'Je näher am Muskelversagen, desto mehr Wachstum – echtes Versagen ist aber nicht nötig. Sätze mit 0–3 Wiederholungen Reserve sind ein guter Kompromiss aus Reiz und Ermüdung.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'strong', 0, true),
  ('4d8f6437-3b39-5af7-a8b3-6d59971dfa2d', 'rir.hypertrophy.compound', 'proximity_to_failure', 'hypertrophy', null, 'compound', null, null, null, 1, 3, 'rir', 'Anstrengung', 'Lass {min}–{max} Wiederholungen im Tank', 'Bei Grundübungen kostet Training bis zum Versagen viel Erholung und erhöht das Technikrisiko – ein bis drei Wiederholungen Reserve liefern fast den gleichen Reiz.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('b9d0adec-71c9-5a0b-8791-3e1bfefc458c', 'rir.hypertrophy.isolation', 'proximity_to_failure', 'hypertrophy', null, 'isolation', null, null, null, 0, 2, 'rir', 'Anstrengung', 'Geh nah ans Versagen: {min}–{max} Wiederholungen im Tank', 'Isolationsübungen sind sicher bis nah ans Versagen und ermüden den Körper insgesamt wenig – hier lohnt sich der letzte Einsatz.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('49748878-03f6-57e3-82df-72d32d5c229f', 'rir.beginner.compound', 'proximity_to_failure', null, 'beginner', 'compound', null, null, null, 2, 4, 'rir', 'Anstrengung', 'Lass {min}–{max} Wiederholungen im Tank', 'Einsteiger schätzen ihre Reserve noch ungenauer ein und lernen die Technik. Auch mit etwas Abstand zum Versagen wachsen Muskeln zuverlässig.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('4d6b50fe-4693-55d2-9d7a-ce0d046d2d5b', 'rir.beginner.isolation', 'proximity_to_failure', null, 'beginner', 'isolation', null, null, null, 1, 3, 'rir', 'Anstrengung', 'Lass {min}–{max} Wiederholungen im Tank', 'Ein bis drei Wiederholungen Reserve: fordernd, aber mit sauberer Technik – das Gefühl für die Reserve wird mit jeder Woche genauer.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('f722f35a-4bdf-5680-ae81-6a8595441a0a', 'rir.strength', 'proximity_to_failure', 'strength', null, null, null, null, null, 1, 3, 'rir', 'Anstrengung', 'Lass {min}–{max} Wiederholungen im Tank', 'Kraftzuwächse hängen kaum davon ab, wie nah am Versagen trainiert wird – Reserve schont die Erholung.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('bcb69227-ad2a-5280-a1d3-4d5168715d7a', 'rir.endurance', 'proximity_to_failure', 'endurance', null, null, null, null, null, 1, 3, 'rir', 'Anstrengung', 'Lass {min}–{max} Wiederholungen im Tank', 'Bei hohen Wiederholungszahlen ist das Versagen schwer abzuschätzen – etwas Reserve hält die Technik sauber.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'limited', 0, true),
  ('d622569e-03d0-52c7-adda-c9ee106f390f', 'rir.hinge', 'proximity_to_failure', null, null, null, null, 'hinge', null, 2, 3, 'rir', 'Anstrengung', 'Bleib bei {min}–{max} Wiederholungen im Tank', 'Hüftbeugen wie Kreuzheben ermüden den ganzen Körper stark und die Technik bricht kurz vor dem Versagen oft ein. Etwas mehr Reserve kostet kaum Wachstum.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'expert_opinion', 0, true),
  ('2ddeb4b1-416e-5a3b-94c0-58b5ad29c56a', 'rir.barbell-back-squat', 'proximity_to_failure', null, null, null, null, null, '5ce59da1-284a-5395-b31b-ceb00638f72e', 2, 3, 'rir', 'Anstrengung', 'Bleib bei {min}–{max} Wiederholungen im Tank', 'Schwere Kniebeugen ermüden stark und sind ohne Spotter riskant – lieber Reserve lassen und die Beine an der Beinpresse ans Versagen bringen.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'expert_opinion', 0, true),
  ('54bd074c-8aa0-55a1-a93a-59222d4cd76f', 'rest.compound', 'rest_interval', null, null, 'compound', null, null, null, 120, 180, 'seconds', 'Pause', '{min}–{max} Sekunden Pause', 'Längere Pausen bei Grundübungen erhalten die Leistung im nächsten Satz – das brachte mehr Kraft und Muskelwachstum als kurze Pausen.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('f4a5a73e-b7ec-58b6-ad68-ba672f165a7d', 'rest.isolation', 'rest_interval', null, null, 'isolation', null, null, null, 60, 120, 'seconds', 'Pause', '{min}–{max} Sekunden Pause', 'Mehr als 60 Sekunden Pause bringen einen kleinen Vorteil fürs Wachstum, über etwa 90 Sekunden hinaus kaum noch.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('7b50344a-b063-583d-bce6-df76ca7fd758', 'rest.strength.compound', 'rest_interval', 'strength', null, 'compound', null, null, null, 180, 300, 'seconds', 'Pause', '{min}–{max} Sekunden Pause', 'Für maximale Kraft brauchen Trainierte meist mehr als zwei Minuten Pause zwischen schweren Sätzen.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'strong', 0, true),
  ('70ff735a-e1b5-538c-9620-479a51271342', 'rest.endurance.compound', 'rest_interval', 'endurance', null, 'compound', null, null, null, 60, 120, 'seconds', 'Pause', '{min}–{max} Sekunden Pause', 'Für Kraftausdauer werden kürzere Pausen empfohlen.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('339bd69c-c6a1-515a-86ad-debe53fab747', 'rest.endurance.isolation', 'rest_interval', 'endurance', null, 'isolation', null, null, null, 30, 60, 'seconds', 'Pause', '{min}–{max} Sekunden Pause', 'Für Kraftausdauer werden kurze Pausen empfohlen.', 'info', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('0a5ac4eb-3072-5fcb-80c0-3060a4bc85aa', 'tempo.default', 'tempo', null, null, null, null, null, null, 0.5, 8, 'seconds', 'Tempo', 'Kontrolliert ab, kraftvoll hoch – {min} bis {max} Sekunden pro Wiederholung', 'Wiederholungsdauern von 0,5 bis 8 Sekunden bringen ähnliches Wachstum. Sehr langsames Training (über 10 Sekunden) schneidet schlechter ab.', 'info', '{exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('e5dd70a1-07fa-5f69-96f4-219fa6ef0c93', 'rom.default', 'range_of_motion', null, null, null, null, null, null, null, null, 'qualitative', 'Bewegungsumfang', 'Volle Bewegung – besonders die gedehnte Position nicht abkürzen', 'Training in gedehnter Position ist mindestens so wirksam wie die volle Bewegung, oft wirksamer. Abgekürzte Wiederholungen im verkürzten Bereich bringen am wenigsten.', 'info', '{exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('78ef9bd3-51b3-5512-b692-7bd921ddf2bc', 'rom.calves', 'range_of_motion', null, null, null, 'd9b74b4a-c3e0-5014-b62e-96a11fc667be', null, null, null, null, 'qualitative', 'Bewegungsumfang', 'Tief in die Dehnung, unten 1–2 Sekunden halten – Teilwiederholungen unten sind eine gute Ergänzung', 'Wadenheben nur im gedehnten Bereich brachte in einer Studie am inneren Wadenmuskel gut doppelt so viel Wachstum wie die volle Bewegung.', 'info', '{exercise_detail,workout_tracker}'::public.guideline_context[], 'limited', 0, true),
  ('71487490-4ba9-5a73-b69f-116bbd084ec3', 'focus.isolation', 'attentional_focus', null, null, 'isolation', null, null, null, null, null, 'qualitative', 'Fokus', 'Konzentrier dich darauf, den Zielmuskel arbeiten zu spüren', 'Bewusstes Anspannen des Zielmuskels brachte bei Curls fast doppelt so viel Bizepswachstum wie ein Fokus auf die Bewegung.', 'info', '{exercise_detail,workout_tracker}'::public.guideline_context[], 'limited', 0, true),
  ('845b3c9d-3b88-5a0a-9f2a-5fa41cb49c0f', 'technique.compound', 'intensity_technique', null, null, 'compound', null, null, null, null, 0, 'sets_per_exercise', 'Intensitätstechniken', 'Keine Dropsätze oder Myo-Reps bei Grundübungen', 'Bei schweren Mehrgelenksübungen gehen Technik und Sicherheit vor. Pump-Techniken gehören an Isolationsübungen.', 'info', '{plan_builder,exercise_detail}'::public.guideline_context[], 'expert_opinion', 0, true),
  ('7d640042-de7b-5d2f-82da-9e91940301eb', 'technique.isolation', 'intensity_technique', null, null, 'isolation', null, null, null, 0, 1, 'sets_per_exercise', 'Pump-Finisher', 'Optional: höchstens {max} Technik-Satz (Dropsatz, Myo-Reps) als Abschluss', 'Dropsätze und Rest-Pause bringen ähnliches Wachstum wie normale Sätze, sparen aber Zeit und sorgen für viel Pump. Der Pump selbst ist kein belegter Wachstumstreiber – das Hauptsignal ist mechanische Spannung.', 'tip', '{plan_builder,exercise_detail,workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('fa2dc67d-e732-559e-a899-d6d1e21680d5', 'technique.beginner.isolation', 'intensity_technique', null, 'beginner', 'isolation', null, null, null, null, 0, 'sets_per_exercise', 'Intensitätstechniken', 'Noch keine Dropsätze – erst Technik und Gefühl für die Reserve aufbauen', 'Einsteiger wachsen mit normalen Sätzen ohnehin schnell. Intensitätstechniken lohnen sich später.', 'info', '{plan_builder,exercise_detail}'::public.guideline_context[], 'expert_opinion', 0, true),
  ('3b937f8c-2462-59c7-b4ed-0f14329297e6', 'progression.double', 'progression', null, null, null, null, null, null, 2, 10, 'percent', 'Steigerung', 'Erst Wiederholungen steigern. Schaffst du in allen Sätzen das obere Ende, kommt beim nächsten Mal mehr Gewicht drauf.', 'Ob über Gewicht oder Wiederholungen gesteigert wird, macht fürs Wachstum kaum einen Unterschied. Positionspapiere empfehlen +2–10 % Last, sobald die Zielwiederholungen übertroffen werden.', 'info', '{exercise_detail,workout_tracker}'::public.guideline_context[], 'strong', 0, true),
  ('c68ec298-bc44-59c6-8380-b16406118a8f', 'autoregulation.rir', 'autoregulation', null, null, null, null, null, null, null, null, 'qualitative', 'Gewicht anpassen', 'Hast du 2+ Wiederholungen mehr im Tank als geplant, nimm im nächsten Satz mehr Gewicht – bei weniger Reserve weniger.', 'Steuerung über die Wiederholungsreserve war in Studien starren Prozentvorgaben mindestens ebenbürtig und passt sich der Tagesform an.', 'info', '{workout_tracker}'::public.guideline_context[], 'moderate', 0, true),
  ('d99035cc-1426-5ddd-951c-b2c8b78b00f3', 'volume.hypertrophy', 'weekly_volume', 'hypertrophy', null, null, null, null, null, 10, 20, 'sets_per_week', 'Wochenvolumen', '{min}–{max} harte Sätze pro Muskel und Woche', 'Mehr Volumen bringt mehr Wachstum, mit abnehmendem Zusatznutzen. Ab etwa 10 Sätzen pro Woche ist der Effekt deutlich. Zum reinen Erhalt reicht viel weniger – deshalb bekommen Prioritätsmuskeln mehr, die übrigen weniger.', 'info', '{plan_builder,analytics}'::public.guideline_context[], 'strong', 0, true),
  ('908a2efd-ffc1-51a5-a478-6aea1d828eca', 'volume.hypertrophy.beginner', 'weekly_volume', 'hypertrophy', 'beginner', null, null, null, null, 6, 12, 'sets_per_week', 'Wochenvolumen', '{min}–{max} harte Sätze pro Muskel und Woche', 'Einsteiger reagieren schon auf wenig Volumen. Gesteigert wird schrittweise von Mesozyklus zu Mesozyklus.', 'info', '{plan_builder,analytics}'::public.guideline_context[], 'limited', 0, true),
  ('4f18db47-cdbd-5948-a8ed-27c298e04cd3', 'volume.strength', 'weekly_volume', 'strength', null, null, null, null, null, 6, 12, 'sets_per_week', 'Wochenvolumen', '{min}–{max} harte Sätze pro Muskel und Woche', 'Für Kraft flacht der Nutzen zusätzlicher Sätze früher ab als für Muskelwachstum.', 'info', '{plan_builder,analytics}'::public.guideline_context[], 'moderate', 0, true),
  ('ebaf643f-f4d9-5a6b-aeae-66ec8319ec65', 'volume.endurance', 'weekly_volume', 'endurance', null, null, null, null, null, 6, 12, 'sets_per_week', 'Wochenvolumen', '{min}–{max} Sätze pro Muskel und Woche', 'Für Kraftausdauer reichen moderate Satzzahlen mit hohen Wiederholungen.', 'info', '{plan_builder,analytics}'::public.guideline_context[], 'limited', 0, true),
  ('c03473e9-4751-54f9-a8aa-a952d5970c4d', 'volume.abs', 'weekly_volume', null, null, null, 'd2a9b03e-ad09-5629-a834-8293335c9923', null, null, 4, 10, 'sets_per_week', 'Wochenvolumen Bauch', '{min}–{max} Sätze pro Woche', 'Der Bauch arbeitet bei vielen Grundübungen stabilisierend mit. Direktes Training reicht in kleinerer Dosis.', 'info', '{plan_builder,analytics}'::public.guideline_context[], 'expert_opinion', 0, true),
  ('df7960bb-522d-5ec7-980c-88f033455524', 'session_volume.default', 'session_volume', null, null, null, null, null, null, null, 10, 'sets_per_session', 'Sätze pro Einheit', 'Mehr als {max} harte Sätze pro Muskel und Einheit bringen kaum Zusatznutzen – lieber auf mehrere Tage verteilen', 'Expertenkonsens: Sehr viele Sätze für denselben Muskel in einer Einheit werden zunehmend ermüdet und wenig produktiv („Junk Volume“).', 'warning', '{plan_builder,workout_tracker}'::public.guideline_context[], 'expert_opinion', 0, true),
  ('93710d15-35ca-57c8-bcfc-05517ecb1f73', 'session_volume.beginner', 'session_volume', null, 'beginner', null, null, null, null, null, 6, 'sets_per_session', 'Sätze pro Einheit', 'Höchstens {max} harte Sätze pro Muskel und Einheit', 'Einsteiger brauchen mehr Erholung für Sehnen und Gelenke und wachsen schon mit wenigen Sätzen.', 'warning', '{plan_builder,workout_tracker}'::public.guideline_context[], 'expert_opinion', 0, true),
  ('a34bb6f4-c060-51b7-8b08-d5518633c8ad', 'frequency.default', 'frequency', null, null, null, null, null, null, 2, 3, 'sessions_per_week', 'Frequenz', 'Jeden Muskel {min}–{max}× pro Woche trainieren', 'Bei gleichem Wochenvolumen ist die Frequenz zweitrangig. Zwei oder mehr Einheiten pro Muskel verteilen das Volumen aber besser und halten jede Einheit produktiv.', 'info', '{plan_builder,analytics}'::public.guideline_context[], 'moderate', 0, true),
  ('8fea5f45-3cf4-552b-bc8a-8489b24712fb', 'volume_progression.mesocycle', 'volume_progression', null, null, null, null, null, null, null, 20, 'percent', 'Volumen anpassen', 'Am Ende eines Mesozyklus: Volumen um bis zu {max} % anpassen – automatisch nur innerhalb des Zielbereichs', 'Ein am bisherigen Training orientiertes, individuelles Volumen brachte mehr Wachstum als ein Einheitsvolumen. Die Schrittweite von höchstens 20 % ist eine vorsichtige Festlegung; oberhalb des Zielbereichs überwiegt die Ermüdung.', 'info', '{plan_builder,analytics}'::public.guideline_context[], 'moderate', 0, true),
  ('ae2ef8b0-f700-51eb-8d3b-8eb88a0d6876', 'exercise_variation.planned', 'exercise_variation', null, null, null, null, null, null, null, null, 'qualitative', 'Übungswechsel', 'Ankerübungen mindestens einen Mesozyklus behalten – gezielt variieren, nicht zufällig', 'Gezielte Variation fördert das Wachstum einzelner Muskelregionen und die Motivation. Zu häufige oder zufällige Wechsel bremsen Fortschritt und machen ihn unmessbar.', 'info', '{plan_builder,analytics}'::public.guideline_context[], 'moderate', 0, true),
  ('261f9142-3091-56c4-bcbb-1d2b73cd4f8a', 'deload.as_needed', 'deload', null, null, null, null, null, null, 5, 6, 'weeks', 'Leichtere Woche', 'Nur bei Bedarf – üblich ist etwa alle {min}–{max} Wochen eine leichtere Woche', 'Eine Pausenwoche brachte kein zusätzliches Muskelwachstum. Sie hilft aber gegen angesammelte Ermüdung und ist in der Praxis etwa alle 5–6 Wochen üblich.', 'info', '{plan_builder,analytics}'::public.guideline_context[], 'limited', 0, true)
